function renderBookmark(b) {
  const li = el('li', { className: 'bookmark' });
  li.dataset.id = b.id;

  if (b.faviconUrl) {
    const img = el('img', { className: 'favicon', src: b.faviconUrl, alt: '', loading: 'lazy' });
